import numpy as np


class DominantFocusedFeasibilityES:
    """
    Feasibility-first mixed-integer (mu+lambda) ES with surrogate screening.
      * Ridge surrogates for per-constraint violations, infeasibility probability,
        and the objective on feasible points.
      * Dominant constraint is detected on a recent archive window (frequency x magnitude),
        receives extra weight, and drives repair chains and parent choice.
      * Repair chains descend the weighted violation with surrogate-ranked single-gene moves,
        with a larger budget when feasibility is rare.
      * Once feasible, a share of offspring are surrogate-screened single-gene moves around
        the feasible incumbent (feasible-neighbourhood exploitation).
      * Duplicate filtering avoids re-evaluating identical points.
    """

    def __init__(self, budget=10000, dim=10):
        self.budget = int(budget)
        self.dim = int(dim)

    def __call__(self, func):
        rng = np.random.default_rng()
        dim = self.dim
        budget = self.budget

        lb = np.asarray(func.bounds.lb, dtype=float)
        ub = np.asarray(func.bounds.ub, dtype=float)
        vt = [str(v) for v in func.variable_types]
        cont = np.array([v == "continuous" for v in vt])
        binm = np.array([v == "binary" for v in vt])
        ordm = np.array([v == "ordinal" for v in vt])
        nvals = np.ones(dim, dtype=int)
        if np.any(~cont):
            nv_all = np.asarray(func.n_values, dtype=int)
            nvals[~cont] = nv_all[~cont]
        ci = np.where(cont)[0]
        di = np.where(~cont)[0]
        cont_set = set(ci.tolist())
        span = ub - lb
        m = int(getattr(func, "n_constraints", 1))

        st = {"n_eval": 0, "best_f": np.inf, "best_x": None, "best_s": 0.2,
              "min_v": np.inf, "dom": 0, "n_feas": 0}
        w = np.ones(m)
        pf = 0.45
        tau = 1.0 / np.sqrt(max(dim, 1))
        WIN = 400

        arch_X, arch_G, arch_f, arch_v = [], [], [], []
        seen = set()
        sur = {"B": None, "bf": None, "C": None}

        def key(x):
            return tuple(np.round(x, 6))

        def sample():
            x = np.empty(dim)
            if len(ci):
                x[ci] = rng.uniform(lb[ci], ub[ci])
            if len(di):
                x[di] = rng.integers(0, nvals[di])
            return x

        def repair(x):
            if len(ci):
                x[ci] = np.clip(x[ci], lb[ci], ub[ci])
            if len(di):
                x[di] = np.clip(np.rint(x[di]), 0, nvals[di] - 1)
            return x

        def feat(X):
            X = np.atleast_2d(X)
            n = X.shape[0]
            blocks = [np.ones((n, 1))]
            if len(ci):
                blocks.append(X[:, ci])
            for j in di:
                k = int(nvals[j])
                oh = np.zeros((n, k))
                idx = np.clip(np.rint(X[:, j]).astype(int), 0, k - 1)
                oh[np.arange(n), idx] = 1.0
                blocks.append(oh)
            return np.hstack(blocks)

        def make_ind(x, s):
            if st["n_eval"] >= budget:
                return None
            st["n_eval"] += 1
            seen.add(key(x))
            f, g = func(x)
            f = float(f)
            g = np.atleast_1d(np.asarray(g, dtype=float))
            g = np.nan_to_num(g, nan=1e6, posinf=1e6, neginf=0.0)
            g = np.maximum(g, 0.0)
            v = float(np.sum(g))
            if not np.isfinite(f):
                f = 1e300
                v = max(v, 1.0)
            if v == 0.0:
                st["n_feas"] += 1
                if f < st["best_f"]:
                    st["best_f"] = f
                    st["best_x"] = x.copy()
                    st["best_s"] = s
            if v < st["min_v"]:
                st["min_v"] = v
            arch_X.append(x.copy())
            arch_G.append(g.copy())
            arch_f.append(f)
            arch_v.append(v)
            return {"x": x.copy(), "s": s, "f": f, "g": g, "v": v}

        def wviol(ind):
            return float(np.dot(w, ind["g"]))

        def update_weights(pop):
            # dominant-constraint statistics from a recent archive window
            if arch_G:
                G = np.array(arch_G[-WIN:])
            elif pop:
                G = np.array([ind["g"] for ind in pop])
            else:
                return
            viol = G > 0.0
            frac = np.mean(viol, axis=0)
            cnt = np.maximum(np.sum(viol, axis=0), 1)
            mag = np.sum(G, axis=0) / cnt
            mag_n = mag / (mag.max() + 1e-12)
            w[:] = 1.0 + 3.0 * frac + 2.0 * mag_n
            score = frac * (mag + 1e-12)
            st["dom"] = int(np.argmax(score))
            w[st["dom"]] *= 2.0

        def rank(pop):
            pop = list(pop)
            n = len(pop)
            for _ in range(n):
                swapped = False
                for j in range(n - 1):
                    a, b = pop[j], pop[j + 1]
                    fa, fb = a["v"] == 0.0, b["v"] == 0.0
                    if fa and fb:
                        swap = a["f"] > b["f"]
                    elif fa != fb:
                        swap = fb
                    else:
                        if rng.random() < pf:
                            swap = a["f"] > b["f"]
                        else:
                            swap = wviol(a) > wviol(b)
                    if swap:
                        pop[j], pop[j + 1] = b, a
                        swapped = True
                if not swapped:
                    break
            return pop

        def mutate(x, s, rate):
            c = x.copy()
            s_new = float(np.clip(s * np.exp(tau * rng.standard_normal()), 1e-3, 0.5))
            if len(ci):
                pc = min(1.0, max(1.0 / len(ci), rate))
                mask = rng.random(len(ci)) < pc
                if not np.any(mask):
                    mask[rng.integers(len(ci))] = True
                c[ci[mask]] += s_new * span[ci[mask]] * rng.standard_normal(int(mask.sum()))
            pm = min(0.5, rate)
            for j in di:
                if nvals[j] <= 1 or rng.random() >= pm:
                    continue
                if binm[j]:
                    c[j] = 1.0 - c[j]
                elif ordm[j]:
                    if rng.random() < 0.7:
                        step = 1.0 if rng.random() < 0.5 else -1.0
                        new = c[j] + step
                        if new < 0 or new > nvals[j] - 1:
                            new = c[j] - step
                        c[j] = new
                    else:
                        c[j] = rng.integers(nvals[j])
                else:
                    r = rng.integers(nvals[j] - 1)
                    cur = int(c[j])
                    c[j] = r if r < cur else r + 1
            return repair(c), s_new

        def sparse_mutate(x, s):
            c = x.copy()
            n_genes = 1 if rng.random() < 0.7 else 2
            genes = rng.choice(np.arange(dim), size=min(n_genes, dim), replace=False)
            for j in genes:
                if j in cont_set:
                    c[j] += 0.3 * s * span[j] * rng.standard_normal()
                else:
                    k = int(nvals[j])
                    if k <= 1:
                        continue
                    if binm[j]:
                        c[j] = 1.0 - c[j]
                    else:
                        r = rng.integers(k - 1)
                        cur = int(c[j])
                        c[j] = r if r < cur else r + 1
            return repair(c), s

        def crossover(p1x, p2x):
            c = p1x.copy()
            if len(di):
                mask = rng.random(len(di)) < 0.5
                c[di] = np.where(mask, p1x[di], p2x[di])
            if len(ci):
                a = rng.random(len(ci))
                c[ci] = a * p1x[ci] + (1.0 - a) * p2x[ci]
            return repair(c)

        def tournament(pop):
            i, j = rng.integers(len(pop), size=2)
            return pop[min(i, j)]

        def dom_parent(pop, k=3):
            cands = [pop[rng.integers(len(pop))] for _ in range(k)]
            dom = st["dom"]
            return min(cands, key=lambda ind: (ind["g"][dom], wviol(ind)))

        def dom_elite_ind():
            # archive individual (recent window) minimising the dominant constraint
            if not arch_G:
                return None
            G = np.array(arch_G[-WIN:])
            base = len(arch_G) - len(G)
            i = int(np.argmin(G[:, st["dom"]] + 1e-9 * G.sum(axis=1)))
            return {"x": arch_X[base + i].copy(), "s": 0.2, "g": G[i].copy(),
                    "v": float(np.sum(G[i])), "f": arch_f[base + i]}

        def fit_surrogate():
            n = len(arch_X)
            if n < 12:
                return False
            Xa = np.array(arch_X[-1500:])
            Ga = np.array(arch_G[-1500:])
            F = feat(Xa)
            D = F.shape[1]
            A = F.T @ F + 1.0 * np.eye(D)
            sur["B"] = np.linalg.solve(A, F.T @ Ga)
            Ya = (Ga > 0.0).astype(float)
            sur["C"] = np.linalg.solve(A, F.T @ Ya)
            fe = [i for i in range(n) if arch_v[i] == 0.0 and arch_f[i] < 1e299]
            fe = fe[-1000:]
            if len(fe) >= 6:
                Xf = np.array([arch_X[i] for i in fe])
                yf = np.array([arch_f[i] for i in fe])
                Ff = feat(Xf)
                Af = Ff.T @ Ff + 1.0 * np.eye(Ff.shape[1])
                sur["bf"] = np.linalg.solve(Af, Ff.T @ yf)
            else:
                sur["bf"] = None
            return True

        def screen_scores(F):
            V = np.maximum(F @ sur["B"], 0.0)
            vp = V @ w
            pinf = np.clip(F @ sur["C"], 0.0, 1.0) @ w / max(np.sum(w), 1e-12)
            return vp + 0.8 * pinf + 0.5 * V[:, st["dom"]]

        def select(cands, k):
            if len(cands) <= k:
                return cands
            X = np.array([c[0] for c in cands])
            F = feat(X)
            score = screen_scores(F)
            order = np.argsort(score)
            n_top = min(len(cands), 2 * k)
            top = order[:n_top]
            if sur["bf"] is not None:
                fp = F[top] @ sur["bf"]
                top_sorted = top[np.argsort(fp)]
            else:
                top_sorted = top
            n_rand = int(round(0.12 * k))
            chosen = list(top_sorted[:max(0, k - n_rand)])
            rest = order[n_top:]
            if n_rand > 0 and len(rest) > 0:
                pick = rng.choice(rest, size=min(n_rand, len(rest)), replace=False)
                chosen.extend(list(pick))
            if len(chosen) < k:
                used = set(int(c) for c in chosen)
                for i in order:
                    if len(chosen) >= k:
                        break
                    if int(i) not in used:
                        chosen.append(i)
                        used.add(int(i))
            return [cands[int(i)] for i in chosen[:k]]

        def repair_chain(base, cap):
            """Greedy surrogate-guided descent of weighted violation (dominant-aware)."""
            cur = base
            spent = 0
            while cur["v"] > 0.0 and spent < cap and st["n_eval"] < budget:
                moves = []
                for j in di:
                    k = int(nvals[j])
                    if k <= 1:
                        continue
                    for v in range(k):
                        if v == int(cur["x"][j]):
                            continue
                        y = cur["x"].copy()
                        y[j] = v
                        moves.append((y, cur["s"]))
                if len(ci):
                    for _ in range(max(3, len(ci) // 2)):
                        y = cur["x"].copy()
                        j = ci[rng.integers(len(ci))]
                        y[j] += 0.05 * span[j] * rng.standard_normal()
                        moves.append((repair(y), cur["s"]))
                moves = [mv for mv in moves if key(mv[0]) not in seen]
                if not moves:
                    break
                if sur["B"] is not None:
                    X = np.array([mv[0] for mv in moves])
                    sc = screen_scores(feat(X))
                    order = np.argsort(sc)
                else:
                    order = rng.permutation(len(moves))
                improved = False
                cur_w = wviol(cur)
                cur_dom = cur["g"][st["dom"]]
                for idx in order[:8]:
                    if spent >= cap or st["n_eval"] >= budget:
                        break
                    y, sy = moves[int(idx)]
                    ind = make_ind(y, sy)
                    if ind is None:
                        break
                    spent += 1
                    if ind["v"] == 0.0 or wviol(ind) < cur_w or ind["g"][st["dom"]] < cur_dom:
                        cur = ind
                        improved = True
                        break
                if not improved:
                    break
            return cur

        def feasible_neighbour(s0):
            # surrogate-screened single-gene moves around the feasible incumbent
            base = st["best_x"]
            cands = []
            for _ in range(24):
                cx, cs = sparse_mutate(base, s0)
                cands.append((cx, cs))
            X = np.array([c[0] for c in cands])
            sc = screen_scores(feat(X)) if sur["B"] is not None else rng.permutation(len(cands))
            return cands[int(np.argmin(sc))]

        def gen(pop, feas_pop, no_feas, p_inc, p_feas):
            r = rng.random()
            rate = rng.choice([1.0, 2.0, 4.0]) / dim
            if st["best_x"] is not None and r < p_inc:
                if rng.random() < 0.5 and sur["B"] is not None:
                    return feasible_neighbour(st["best_s"])
                return mutate(st["best_x"], st["best_s"], rate)
            if feas_pop and r < p_inc + p_feas:
                a = feas_pop[rng.integers(len(feas_pop))]
                cx, cs = mutate(a["x"], a["s"], rate)
                if rng.random() < 0.3 and len(feas_pop) > 1:
                    b = feas_pop[rng.integers(len(feas_pop))]
                    cx = crossover(cx, b["x"])
                    cx, cs = mutate(cx, cs, rate / 2.0)
                return cx, cs
            if no_feas and rng.random() < 0.15:
                ex = dom_elite_ind()
                if ex is not None:
                    return mutate(ex["x"], 0.2, rate)
            if no_feas and rng.random() < 0.5:
                a = dom_parent(pop)
                return sparse_mutate(a["x"], a["s"])
            a = dom_parent(pop)
            if rng.random() < 0.5:
                b = feas_pop[rng.integers(len(feas_pop))] if feas_pop else tournament(pop)
                cx = crossover(a["x"], b["x"])
                cs = 0.5 * (a["s"] + b["s"])
                return mutate(cx, cs, 1.0 / dim)
            return sparse_mutate(a["x"], a["s"])

        def local_sweep(x0, s0):
            cur = x0.copy()
            for j in rng.permutation(di) if len(di) else []:
                if st["n_eval"] >= budget:
                    break
                k = int(nvals[j])
                if k <= 1:
                    continue
                if k <= 6:
                    cands = [v for v in range(k) if v != int(cur[j])]
                else:
                    cands = list(rng.choice([v for v in range(k) if v != int(cur[j])],
                                            size=4, replace=False))
                for v in cands:
                    if st["n_eval"] >= budget:
                        break
                    y = cur.copy()
                    y[j] = v
                    ind = make_ind(y, s0)
                    if ind is None:
                        break
                    if ind["v"] == 0.0 and ind["f"] <= st["best_f"]:
                        cur = y.copy()
                        break
            if len(ci):
                for _ in range(min(10, 2 * len(ci))):
                    if st["n_eval"] >= budget:
                        break
                    y = cur.copy()
                    idx = rng.integers(len(ci))
                    j = ci[idx]
                    y[j] = y[j] + 0.02 * span[j] * rng.standard_normal()
                    y = repair(y)
                    ind = make_ind(y, s0)
                    if ind is None:
                        break
                    if ind["v"] == 0.0 and ind["f"] <= st["best_f"]:
                        cur = y.copy()

        # ---------- parameters ----------
        P = int(max(8, min(10 + 2 * dim, budget // 8)))
        stag_limit = 12
        p_inc = 0.2
        p_feas = 0.4

        # ---------- initial population ----------
        n_init = int(max(P, min(4 * P, budget // 10)))
        pop = []
        while len(pop) < n_init and st["n_eval"] < budget:
            ind = make_ind(sample(), 0.2)
            if ind is None:
                break
            pop.append(ind)
        if not pop:
            return np.inf, None
        update_weights(pop)
        pop = rank(pop)[:P]

        prev_best_f = st["best_f"]
        prev_min_v = st["min_v"]
        stagn = 0
        gen_count = 0

        # ---------- main loop ----------
        while st["n_eval"] < budget:
            gen_count += 1
            feas_pop = [ind for ind in pop if ind["v"] == 0.0]
            no_feas = st["best_x"] is None
            feas_rate = st["n_feas"] / max(1, st["n_eval"])
            n_off = min(P, budget - st["n_eval"])
            use_sur = fit_surrogate()

            # targeted repair chains on least-violated and dominant-elite infeasible points
            urgent = no_feas or feas_rate < 0.05
            extra = []
            if use_sur and st["n_eval"] < budget and (urgent or gen_count % 3 == 0):
                infeas = sorted([ind for ind in pop if ind["v"] > 0.0], key=wviol)
                n_rep = 3 if urgent else 1
                cap = 12 if no_feas else 6
                if urgent and no_feas:
                    cap = 14
                bases = infeas[:n_rep]
                if urgent:
                    ex_ind = dom_elite_ind()
                    if ex_ind is not None and ex_ind["v"] > 0.0 and not any(
                            np.array_equal(ex_ind["x"], b["x"]) for b in bases):
                        bases = bases + [ex_ind]
                for base in bases:
                    if st["n_eval"] >= budget:
                        break
                    rep = repair_chain(base, cap)
                    if rep is not base:
                        extra.append(rep)
                if st["n_eval"] >= budget:
                    break

            if use_sur:
                cands = [gen(pop, feas_pop, no_feas, p_inc, p_feas) for _ in range(3 * n_off)]
                chosen = select(cands, n_off)
            else:
                chosen = [gen(pop, feas_pop, no_feas, p_inc, p_feas) for _ in range(n_off)]

            offspring = []
            for cx, cs in chosen:
                ind = make_ind(cx, cs)
                if ind is None:
                    break
                offspring.append(ind)

            if not offspring and not extra:
                break
            combined = pop + offspring + extra
            update_weights(combined)
            pop = rank(combined)[:P]

            if st["best_f"] < prev_best_f or st["min_v"] < prev_min_v:
                stagn = 0
                prev_best_f = st["best_f"]
                prev_min_v = st["min_v"]
            else:
                stagn += 1

            if stagn >= stag_limit and st["n_eval"] < budget:
                stagn = 0
                if st["best_x"] is not None:
                    local_sweep(st["best_x"], st["best_s"])
                    prev_best_f = st["best_f"]
                keep = max(1, P // 5)
                new_pop = pop[:keep]
                n_new = P - keep
                for k in range(n_new):
                    if st["n_eval"] >= budget:
                        break
                    if k % 2 == 0 and st["best_x"] is not None:
                        cx, cs = mutate(st["best_x"], 0.3, 2.0 / dim)
                    else:
                        cx, cs = sample(), 0.3
                    ind = make_ind(cx, cs)
                    if ind is None:
                        break
                    new_pop.append(ind)
                if new_pop:
                    update_weights(new_pop)
                    pop = rank(new_pop)[:P]

        if st["best_x"] is None:
            return np.inf, pop[0]["x"]
        return st["best_f"], st["best_x"]
